import csv
import io


def parse_csv(raw_csv: str):
    reader = csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"')
    try:
        columns = next(reader)
    except StopIteration:
        return {"columns": [], "rows": []}

    if columns:
        columns[0] = columns[0].lstrip("\ufeff")

    width = len(columns)
    rows = []
    for row in reader:
        if width and len(row) > width:
            row = row[:width - 1] + [",".join(row[width - 1:])]
        elif len(row) < width:
            row += [""] * (width - len(row))
        rows.append(row)

    return {"columns": columns, "rows": rows}
